for v,(N,probs,obs) in enumerate([(120,['1/2','1/3','1/6'],[54,44,22]),(100,['1/5','3/10','1/2'],[18,33,49])],1):
 E=[N*s.Rational(z) for z in probs];stat=sum((o-e)**2/e for o,e in zip(obs,E))
 add('specified','K',1,v,'All expectations and the full statistic',r'<p>A specified categorical model has probabilities \(('+','.join(tex(z) for z in probs)+r')\). For '+str(N)+r' independent observations, the counts are \(('+','.join(map(str,obs))+r')\). Give all three expected counts and Pearson’s statistic exactly.</p>',[field('e1','First expected count',E[0]),field('e2','Second expected count',E[1]),field('e3','Third expected count',E[2]),field('stat','Pearson statistic',stat)],r'<p>Multiply each model probability by N and add \((O-E)^2/E\) for every class. Do not replace the model probabilities by observed proportions.</p>',dict(kind='categorical',N=N,probabilities=probs,observed=obs,expected=list(map(str,E)),statistic=str(stat)))
for v,N in enumerate([64,80],1):
 E=[s.Rational(N,8),s.Rational(3*N,8),s.Rational(N,2)]
 add('specified','K',2,v,'Include the complete binomial tail',r'<p>The specified model is \(\mathrm B(3,1/2)\). For '+str(N)+r' independent runs the pre-specified test classes are X=0, X=1 and X≥2. Give all three expected counts and the degrees of freedom. No parameter is fitted.</p>',[field('zero','Expected zero-success count',E[0]),field('one','Expected one-success count',E[1]),field('tail','Expected count of at least two',E[2]),field('df','Degrees of freedom',2)],'<p>The probabilities are 1/8, 3/8 and 1/2. The tail includes both 2 and 3 successes. There are three final classes and no fitted parameters.</p>',dict(kind='binomial_classes',N=N,trials=3,p='1/2',groups=[[0],[1],[2,3]],expected=list(map(str,E)),df=2))
for v,(E,O) in enumerate([([40,30,20,7,3],[42,29,16,7,6]),([30,35,28,5,2],[28,36,27,7,2])],1):
 ep=sum(E[-2:]);op=sum(O[-2:]);con=s.Rational((op-ep)**2,ep)
 add('specified','K',3,v,'Pool both counts before calculating a contribution',r'<p>Five ordered classes have expected counts \(('+','.join(map(str,E))+r')\) and observed counts \(('+','.join(map(str,O))+r')\). Combine the last two classes. No parameter is estimated. Give the pooled observed count, pooled expected count, its Pearson contribution and the new degrees of freedom.</p>',[field('observed','Pooled observed count',op),field('expected','Pooled expected count',ep),field('contribution','Pooled contribution',con),field('df','Degrees of freedom',3)],'<p>Add observed and expected counts separately. Then calculate one new contribution. Four classes remain, giving three degrees of freedom.</p>',dict(kind='pool_cell',observed=O,expected=E,group=[3,4],values=list(map(str,[op,ep,con,3]))))
for v,O in enumerate([[9,16,10,4,1],[8,18,10,3,1]],1):
 N=sum(O);total=sum(j*f for j,f in enumerate(O));ss=sum(j*j*f for j,f in enumerate(O));mean=s.Rational(total,N);var=(ss-N*mean**2)/(N-1)
 add('estimated','F',1,v,'Fit the mean before any pooling',r'<p>The complete observed frequencies for counts 0,1,2,3,4 are \(('+','.join(map(str,O))+r')\); no larger value was observed. Estimate a Poisson mean and give the unbiased variance of these counts, exactly.</p>',[field('lambda','Fitted Poisson mean',mean),field('variance','Unbiased sample variance',var)],r'<p>Use the frequency-weighted mean and \([\sum x^2f-(\sum xf)^2/N]/(N-1)\). All original counts are available, so no tail midpoint is needed.</p>',dict(kind='moments',observed=O,trials=None,mean=str(mean),variance=str(var)))
for v,O in enumerate([[6,18,18,6],[3,13,13,3]],1):
 N=sum(O);p=s.Rational(sum(i*f for i,f in enumerate(O)),3*N);zero=N*(1-p)**3
 add('estimated','F',2,v,'Runs, trials and a fitted probability',r'<p>Each independent run contains three trials. The numbers of runs with 0,1,2,3 successes are \(('+','.join(map(str,O))+r')\). Fit \(\mathrm B(3,p)\) and give its expected zero-success frequency exactly. Do not decide on pooling until the expectations are calculated.</p>',[field('p','Fitted success probability',p),field('zero','Expected zero-success count',zero)],'<p>The fitted probability is total successes divided by total trials. Use N(1−p)³ for the zero-success frequency; N counts runs, not individual trials.</p>',dict(kind='fitted_binomial',observed=O,trials=3,p=str(p),zero=str(zero)))
for v,k in enumerate([7,6],1):
 add('estimated','F',3,v,'Three sources of model information',r'<p>After pooling there are '+str(k)+r' classes. Give ν for three analyses: no fitted parameters; one parameter fitted from the test sample; two parameters fitted from the test sample.</p>',[field('fixed','No fitted parameters',k-1),field('one','One fitted parameter',k-2),field('two','Two fitted parameters',k-3)],'<p>Use the final number of classes in ν=k−1−s. Subtract only parameters estimated to fit this model using these data.</p>',dict(kind='df',classes=k,parameters=[0,1,2],expected=list(map(str,[k-1,k-2,k-3]))))
for v,(L,N,O) in enumerate([(2,80,[18,62]),(3,90,[12,78])],1):
 bounds=[0,1,L];E=[s.Rational(N,L*L),N-s.Rational(N,L*L)];stat=sum((o-e)**2/e for o,e in zip(O,E));density=2*s.Symbol('x')/L**2
 add('continuous','C',1,v,'Areas, expectations and a complete statistic',r'<p>The specified density is \('+tex(density)+r'\) on \([0,'+str(L)+r']\), zero elsewhere. In '+str(N)+r' independent readings, the counts below and at/above 1 are \(('+','.join(map(str,O))+r')\). Give both expected counts and Pearson’s statistic exactly.</p>',[field('lower','Expected count below 1',E[0]),field('upper','Expected count at or above 1',E[1]),field('stat','Pearson statistic',stat)],r'<p>Integrate the density from 0 to 1 and from 1 to the upper support boundary. Multiply by N, then add both Pearson contributions.</p>',dict(kind='density_gof',density=str(density),bounds=list(map(str,bounds)),observed=O,expected=list(map(str,E)),statistic=str(stat),df=1))
for v,(L,N,bounds) in enumerate([(10,100,[0,1,4,10]),(8,80,[0,2,3,8])],1):
 E=[s.Rational(N*(b-a),L) for a,b in zip(bounds,bounds[1:])]
 add('continuous','C',2,v,'Unequal class widths',r'<p>The model is uniform on \([0,'+str(L)+r']\). For '+str(N)+r' independent readings the test boundaries are \(('+','.join(map(str,bounds))+r')\). Give the three expected frequencies and degrees of freedom. All parameters were specified in advance.</p>',[field('e1','First expected count',E[0]),field('e2','Second expected count',E[1]),field('e3','Third expected count',E[2]),field('df','Degrees of freedom',2)],'<p>Each class probability equals its width divided by the total support length. Three final classes with no fitted parameters give ν=2.</p>',dict(kind='uniform_classes',L=L,N=N,bounds=bounds,expected=list(map(str,E)),df=2))
for v,(left,right,N) in enumerate([(s.Rational(1,5),s.Rational(1,4),100),(s.Rational(1,10),s.Rational(3,10),80)],1):
 E=[N*left,N*(1-left-right),N*right]
 add('continuous','C',3,v,'Do not discard the exterior tails',r'<p>A fully specified continuous model has \(P(X&lt;a)='+tex(left)+r'\) and \(P(X\ge b)='+tex(right)+r'\), where a&lt;b. There are '+str(N)+r' independent readings and three test classes: the left tail, [a,b), and the right tail. Give all three expected counts exactly.</p>',[field('left','Expected left tail',E[0]),field('middle','Expected middle class',E[1]),field('right','Expected right tail',E[2])],'<p>The middle probability is one minus both tails. Keep the exterior classes even if an observed tail count happens to be zero.</p>',dict(kind='tail_classes',left=str(left),right=str(right),N=N,expected=list(map(str,E))))
def contingency(O,groups=None):
 groups=groups or [[j] for j in range(len(O[0]))];O=[[sum(row[j] for j in g) for g in groups] for row in O];N=sum(map(sum,O));rows=list(map(sum,O));cols=[sum(row[j] for row in O) for j in range(len(O[0]))];E=[[s.Rational(r*c,N) for c in cols] for r in rows];stat=sum((o-e)**2/e for row,erow in zip(O,E) for o,e in zip(row,erow));return E,stat,(len(O)-1)*(len(O[0])-1)
for v,O in enumerate([[[18,12],[12,18]],[[24,16],[16,24]]],1):
 E,stat,df=contingency(O)
 add('contingency','T',1,v,'All four expected cells',r'<p>Independent observations form the two-by-two table with rows \(('+','.join(map(str,O[0]))+r')\) and \(('+','.join(map(str,O[1]))+r')\). Under independence, give all four expected cells in row order, the statistic and ν.</p>',[field('e11','Expected row 1 column 1',E[0][0]),field('e12','Expected row 1 column 2',E[0][1]),field('e21','Expected row 2 column 1',E[1][0]),field('e22','Expected row 2 column 2',E[1][1]),field('stat','Pearson statistic',stat),field('df','Degrees of freedom',df)],'<p>Use row total × column total ÷ grand total in each cell. Sum the four interior contributions and use (2−1)(2−1)=1.</p>',dict(kind='contingency',observed=O,expected=[[str(z) for z in row] for row in E],statistic=str(stat),df=df))
