 add('contingency','T',2,v,'Margins of a three-by-three table',r'<p>A three-by-three table has observed rows '+', '.join(r'\(('+','.join(map(str,row))+r')\)' for row in O)+r'. Give the three expected counts in its first row under independence and the test degrees of freedom.</p>',[field('e1','First-row expected column 1',E[0][0]),field('e2','First-row expected column 2',E[0][1]),field('e3','First-row expected column 3',E[0][2]),field('df','Degrees of freedom',df)],'<p>Find all column totals and the first row total before applying the independence formula. There are (3−1)(3−1)=4 degrees of freedom, not 9−1.</p>',dict(kind='first_row',observed=O,expected=list(map(str,E[0])),df=df))
